<script setup>
import { $api } from '@/utils/api'
const meta=ref({members:[]}), facilities=ref([]), bookings=ref([]), result=ref(null), hold=ref(null), error=ref(''), busy=ref(false)
const cancelOpen=ref(false), cancelTarget=ref(null), cancelPreview=ref(null), cancelReason=ref('')
const form=reactive({member_id:null,facility_id:null,date:new Date(Date.now()+86400000).toISOString().slice(0,10),start_time:'10:00',duration:60,guest_count:0,lighting_requested:false})
const money=(v,c='ZAR')=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:c}).format((v||0)/100)
const payload=()=>{const start=new Date(`${form.date}T${form.start_time}:00+02:00`);return{member_id:form.member_id,facility_id:form.facility_id,starts_at:start.toISOString(),ends_at:new Date(start.getTime()+form.duration*60000).toISOString(),guest_count:form.guest_count,lighting_requested:form.lighting_requested}}
async function load(){[meta.value,facilities.value]=await Promise.all([$api('/booking/facilities/meta'),$api('/booking/facilities')]);bookings.value=(await $api('/bookings')).data}
async function simulate(){busy.value=true;error.value='';try{result.value=await $api('/booking/simulate',{method:'POST',body:payload()})}catch(e){error.value=e?.data?.message||'Slot could not be evaluated.'}finally{busy.value=false}}
async function createHold(){busy.value=true;error.value='';try{hold.value=await $api('/booking/holds',{method:'POST',body:{...payload(),idempotency_key:crypto.randomUUID()}})}catch(e){error.value=e?.data?.message||'Hold could not be created.'}finally{busy.value=false}}
async function confirm(){busy.value=true;error.value='';try{await $api(`/booking/holds/${hold.value.id}/confirm`,{method:'POST',body:{confirmation_key:crypto.randomUUID(),participants:[]}});hold.value=null;result.value=null;await load()}catch(e){error.value=e?.data?.message||'Booking could not be confirmed.'}finally{busy.value=false}}
async function openCancellation(item){busy.value=true;error.value='';try{cancelTarget.value=item;cancelReason.value='';cancelPreview.value=await $api(`/bookings/${item.id}/cancellation-preview`);cancelOpen.value=true}catch(e){error.value=e?.data?.message||'Cancellation could not be previewed.'}finally{busy.value=false}}
async function cancel(){if(!cancelReason.value.trim())return;busy.value=true;error.value='';try{await $api(`/bookings/${cancelTarget.value.id}/cancel`,{method:'POST',body:{reason:cancelReason.value,idempotency_key:crypto.randomUUID()}});cancelOpen.value=false;cancelTarget.value=null;cancelPreview.value=null;await load()}catch(e){error.value=e?.data?.message||'Cancellation could not be completed.'}finally{busy.value=false}}
async function checkIn(item){busy.value=true;error.value='';try{await $api(`/bookings/${item.id}/check-in`,{method:'POST',body:{method:'member'}});await load()}catch(e){error.value=e?.data?.message||'Check-in could not be completed.'}finally{busy.value=false}}
onMounted(load)
</script>
<template><div><div class="mb-6"><h3 class="text-h3">Court bookings</h3><p class="text-medium-emphasis">Day and mobile-list booking with server-calculated rules, allowance and price.</p></div><VAlert v-if="error" type="error" class="mb-4">{{error}}</VAlert>
<VRow><VCol cols="12" lg="5"><VCard><VCardTitle>Find a court</VCardTitle><VCardText><VSelect v-model="form.member_id" :items="meta.members" item-title="display_name" item-value="id" label="Member"/><VSelect v-model="form.facility_id" :items="facilities" item-title="name" item-value="id" label="Facility"/><VRow><VCol cols="7"><VTextField v-model="form.date" type="date" label="Date"/></VCol><VCol cols="5"><VTextField v-model="form.start_time" type="time" label="Start"/></VCol></VRow><VSelect v-model="form.duration" :items="[30,60,90,120]" label="Duration (minutes)"/><VTextField v-model.number="form.guest_count" type="number" min="0" label="Guests"/><VSwitch v-model="form.lighting_requested" label="Add court lighting"/><div class="d-flex gap-2"><VBtn :loading="busy" :disabled="!form.member_id||!form.facility_id" @click="simulate">Check rules and price</VBtn><VBtn v-if="result?.eligible" variant="tonal" @click="createHold">Hold slot</VBtn></div></VCardText></VCard>
<VCard v-if="result" class="mt-4"><VCardTitle>{{result.eligible?'Available':'Not available'}}</VCardTitle><VCardText><p><strong>Profile:</strong> {{result.profile.profile.replaceAll('_',' ')}}</p><p><strong>Price:</strong> {{money(result.price.total_amount,result.price.currency)}} <span v-if="result.price.lighting_amount">({{money(result.price.lighting_amount)}} lighting)</span></p><VAlert v-if="result.lighting" :type="result.lighting.required?'warning':'info'" variant="tonal" class="my-3">{{result.lighting.reason}}<span v-if="result.lighting.applies"> Scheduled {{new Date(result.lighting.scheduled_on_at).toLocaleTimeString()}}–{{new Date(result.lighting.scheduled_off_at).toLocaleTimeString()}}.</span></VAlert><p><strong>Allowance:</strong> {{result.allowance.minutes||0}} minutes / {{money(result.allowance.value_cents)}}</p><p><strong>Cancel by:</strong> {{new Date(result.cancellation.cancellation_deadline).toLocaleString()}}</p><VList density="compact"><VListItem v-for="check in result.checks" :key="check.code" :prepend-icon="check.passed?'tabler-circle-check':'tabler-alert-circle'" :title="check.code.replaceAll('_',' ')" :subtitle="check.passed?'Passed':check.member_message"/></VList></VCardText></VCard>
<VAlert v-if="hold" type="warning" class="mt-4"><div>Held until {{new Date(hold.expires_at).toLocaleTimeString()}}</div><VBtn class="mt-2" size="small" @click="confirm">Confirm booking</VBtn></VAlert></VCol>
<VCol cols="12" lg="7"><VCard><VCardTitle>My and authorized bookings</VCardTitle><VTable><thead><tr><th>Reference</th><th>Court</th><th>Start</th><th>Status</th><th>Payment / lights</th><th/></tr></thead><tbody><tr v-for="item in bookings" :key="item.id"><td>{{item.booking_reference}}</td><td>{{item.facility.name}}</td><td>{{new Date(item.starts_at).toLocaleString()}}</td><td>{{item.status.replaceAll('_',' ')}}<div v-if="item.attendance"><small>Attendance: {{item.attendance.status.replaceAll('_',' ')}}</small></div></td><td><div>{{item.payment_status.replaceAll('_',' ')}}</div><small v-if="item.lighting_reservations?.length">Lights: {{item.lighting_reservations[0].status.replaceAll('_',' ')}}</small><small v-if="item.cancellation_compensation?.credit_note">{{item.cancellation_compensation.credit_note.credit_note_number}}</small><small v-if="item.cancellation_compensation?.refund_request">Refund {{item.cancellation_compensation.refund_request.status.replaceAll('_',' ')}}</small></td><td><div class="d-flex"><VBtn v-if="item.attendance&&!['checked_in','late_checked_in','cancelled','no_show'].includes(item.attendance.status)" size="small" variant="tonal" :loading="busy" @click="checkIn(item)">Check in</VBtn><VBtn v-if="!['cancelled','completed'].includes(item.status)" size="small" variant="text" :loading="busy" @click="openCancellation(item)">Cancel</VBtn></div></td></tr></tbody></VTable></VCard></VCol></VRow>
<VDialog v-model="cancelOpen" max-width="620" persistent><VCard v-if="cancelPreview"><VCardTitle class="pa-6">Cancel {{cancelPreview.booking.booking_reference}}?</VCardTitle><VCardText><p class="text-h6">{{cancelPreview.booking.facility}}</p><p>{{new Date(cancelPreview.booking.starts_at).toLocaleString()}} – {{new Date(cancelPreview.booking.ends_at).toLocaleTimeString()}}</p><VDivider class="my-4"/><VRow><VCol cols="6"><strong>Amount paid</strong><div>{{money(cancelPreview.decision.amount_paid,cancelPreview.decision.currency)}}</div></VCol><VCol cols="6"><strong>Policy band</strong><div>{{cancelPreview.decision.policy_band.replaceAll('_',' ')}}</div></VCol><VCol cols="6"><strong>Expected outcome</strong><div>{{cancelPreview.decision.outcome_type.replaceAll('_',' ')}}</div></VCol><VCol cols="6"><strong>Compensation</strong><div>{{money(cancelPreview.decision.eligible_amount,cancelPreview.decision.currency)}} ({{cancelPreview.decision.compensation_percentage}}%)</div></VCol></VRow><VAlert :type="cancelPreview.decision.requires_finance_review?'warning':'info'" class="my-4">{{cancelPreview.decision.explanation}}</VAlert><p v-if="cancelPreview.decision.allowance_minutes_to_restore">Allowance restored: {{cancelPreview.decision.allowance_minutes_to_restore}} minutes</p><VTextarea v-model="cancelReason" label="Cancellation reason" maxlength="500" counter/></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" :disabled="busy" @click="cancelOpen=false">Keep booking</VBtn><VBtn color="error" :loading="busy" :disabled="cancelReason.trim().length<3" @click="cancel">Confirm cancellation</VBtn></VCardActions></VCard></VDialog>
</div></template>
